FreshInventoryOwnedV4::FreshInventoryOwnedV4(std::uintptr_t id,LootTablesV2::Borrow b,LootRandom8V2& r,std::int8_t cap,std::shared_ptr<PropertyState> props):tables_(std::move(b)),random_(&r),character_(id),properties_(std::move(props)),potion_capacity_(cap){if(!id||!tables_||!properties_)throw std::invalid_argument("Unbound fresh inventory owner");}
FreshInventoryOwnedV4::FreshInventoryOwnedV4(LootTablesV2::Borrow b,LootRandom8V2& r,std::shared_ptr<PropertyState> props):tables_(std::move(b)),random_(&r),character_(0),properties_(std::move(props)),potion_capacity_(-1){if(!tables_||!properties_)throw std::invalid_argument("Unbound source NULL-character drop inventory");}
std::unique_ptr<FreshInventoryOwnedV4> FreshInventoryOwnedV4::create_drop_temporary_v4(LootTablesV2::Borrow b,LootRandom8V2& r,std::shared_ptr<PropertyState> props){return std::unique_ptr<FreshInventoryOwnedV4>(new FreshInventoryOwnedV4(std::move(b),r,std::move(props)));}
bool FreshInventoryOwnedV4::mutation_allowed(std::string& e)const{if(callback_depth_){e="Unsupported destructive inventory callback reentry";return false;}return true;}
void FreshInventoryOwnedV4::observe(const OwnedInventoryServicesV4& s,OwnedInventoryOperationV4 op,std::uint32_t caller,ItemInstanceV1* item,std::int32_t arg,std::uint32_t index){if(s.observe_storage){++callback_depth_;struct Guard{std::uint32_t& n;~Guard(){--n;}}guard{callback_depth_};s.observe_storage(s.context,*this,{op,caller,item,nullptr,arg,index});}}
