const Item* FreshInventoryOwnedV4::metadata(const ItemInstanceV1* instance,std::string& e)const{auto* p=instance?item(tables_.items(),instance->id):nullptr;if(!p)e="Item index requires original assertion continuation";return p;}
std::int32_t FreshInventoryOwnedV4::set_for_slot(std::int32_t slot)const noexcept{return slot<0||slot==1||slot==2?selected_:0;}
std::int8_t& FreshInventoryOwnedV4::slot_for_set(OwnedItemSlotV4& slot,std::uint32_t set)noexcept{return slot.slots[set];}
bool FreshInventoryOwnedV4::inventory_full(bool& out,const OwnedInventoryServicesV4& s,std::string& e){return is_full(out,s,e);}
bool FreshInventoryOwnedV4::is_full(bool& full,const OwnedInventoryServicesV4& s,std::string& e){OwnedInventoryResponseV4 r;if(!deliver(s,OwnedInventoryOperationV4::debug_load,0x3fe364,nullptr,nullptr,0,0,r,e)||!deliver(s,OwnedInventoryOperationV4::debug_query,0x3fe3a8,nullptr,"InfiniteInventory",0,0,r,e))return false;full=!r.value&&!unlimited_&&items_.size()>99;return true;}
bool FreshInventoryOwnedV4::destroy(std::unique_ptr<ItemInstanceV1>& p,const OwnedInventoryServicesV4& s,std::uint32_t caller,std::string& e){if(!p){e="Null source item destruction";return false;}observe(s,OwnedInventoryOperationV4::destroy_item,caller,p.get());p.reset();return true;}
bool FreshInventoryOwnedV4::equal(const ItemInstanceV1& a,const ItemInstanceV1& b)noexcept{return a.id==b.id&&a.powers==b.powers;}
bool FreshInventoryOwnedV4::add_quantity(ItemInstanceV1& p,std::int32_t n,std::string& e){auto q=wrap32(std::uint32_t(p.signed_quantity())+std::uint32_t(n));if(q==-2)q=99;if(q<0){e="Negative SetQty requires original assertion continuation";return false;}p.quantity=std::uint16_t(q);return true;}
bool FreshInventoryOwnedV4::create_item(std::int32_t id,std::uint32_t quantity,std::unique_ptr<ItemInstanceV1>& out,const OwnedInventoryServicesV4& s,std::string& e){if(!mutation_allowed(e))return false;if(out||!item(tables_.items(),id)){e="Malformed constructor output or source item index";return false;}auto p=std::make_unique<ItemInstanceV1>();p->id=id;p->quantity=std::uint16_t(quantity);OwnedInventoryResponseV4 r;for(auto op:{OwnedInventoryOperationV4::update_name,OwnedInventoryOperationV4::update_stats,OwnedInventoryOperationV4::update_requirements})if(!deliver(s,op,op==OwnedInventoryOperationV4::update_name?0x3fc36c:op==OwnedInventoryOperationV4::update_stats?0x3fc374:0x3fc37c,p.get(),nullptr,0,0,r,e))return false;out=std::move(p);e.clear();return true;}
bool FreshInventoryOwnedV4::split_item(ItemInstanceV1& original,std::int32_t amount,std::unique_ptr<ItemInstanceV1>& out,const OwnedInventoryServicesV4& s,std::string& e){if(!mutation_allowed(e))return false;if(out){e="Split output already owns an item";return false;}auto* info=metadata(&original,e);if(!info)return false;if(!std::uint8_t(info->record.words[7])||amount<=0||amount>=original.signed_quantity()){e.clear();return true;}if(!add_quantity(original,-amount,e))return false;if(!create_item(original.id,std::uint32_t(amount),out,s,e))return false;out->value=original.value;OwnedInventoryResponseV4 r;if(!deliver(s,OwnedInventoryOperationV4::update_name,0x3fc44c,out.get(),nullptr,0,0,r,e))return false;out->identified=0;for(std::size_t i=0;i<original.powers.size();++i){if(i>65536){e="Source power iteration exceeds owned budget";return false;}auto id=original.powers[i];if(!deliver(s,OwnedInventoryOperationV4::add_power,0x3fc468,out.get(),nullptr,id,UINT32_MAX,r,e))return false;}out->identified=original.identified;e.clear();return true;}
bool FreshInventoryOwnedV4::is_equipped(std::uint32_t index,bool& out,std::string& e)const{if(index>=items_.size()||!items_[index]||!items_[index]->item){e="Equipped query requires original valid slot";return false;}auto* p=metadata(items_[index]->item.get(),e);if(!p)return false;auto slot=p->record.words[26];auto set=slot>=0||slot<-4?set_for_slot(slot):slot==-2?set_for_slot(5):slot==-1?set_for_slot(-1):set_for_slot(1);out=items_[index]->slots[set]!=-1;e.clear();return true;}
